package com.example.incidentapp.viewmodel;
import androidx.lifecycle.*;import com.example.incidentapp.model.*;import com.example.incidentapp.repository.*;import com.example.incidentapp.util.*;import java.util.*;import retrofit2.*;
public class MapaViewModel extends ViewModel{private final CatalogoRepository cat=new CatalogoRepository();private final UbicacionRepository ubi=new UbicacionRepository();private final MutableLiveData<List<Sucursal>> suc=new MutableLiveData<>(Collections.emptyList());private final MutableLiveData<List<TecnicoUbicacion>> tec=new MutableLiveData<>(Collections.emptyList());private final MutableLiveData<Boolean> loading=new MutableLiveData<>(false);private final MutableLiveData<Event<String>> mensaje=new MutableLiveData<>();public LiveData<List<Sucursal>> getSucursales(){return suc;}public LiveData<List<TecnicoUbicacion>> getTecnicos(){return tec;}public LiveData<Boolean> getLoading(){return loading;}public LiveData<Event<String>> getMensaje(){return mensaje;}public void cargarSucursales(boolean todas){loading.setValue(true);cat.obtenerSucursales(todas).enqueue(new Callback<SucursalesResponse>(){public void onResponse(Call<SucursalesResponse>c,Response<SucursalesResponse>r){loading.setValue(false);if(r.isSuccessful()&&r.body()!=null&&r.body().getSucursales()!=null)suc.setValue(r.body().getSucursales());else mensaje.setValue(new Event<>(ApiErrorUtils.obtenerMensaje(r,"No se pudieron cargar las sucursales")));}public void onFailure(Call<SucursalesResponse>c,Throwable t){loading.setValue(false);mensaje.setValue(new Event<>("No se pudo conectar con la API"));}});}public void cargarTecnicos(){ubi.listar().enqueue(new Callback<UbicacionesTecnicosResponse>(){public void onResponse(Call<UbicacionesTecnicosResponse>c,Response<UbicacionesTecnicosResponse>r){if(r.isSuccessful()&&r.body()!=null)tec.setValue(r.body().getTecnicos()==null?Collections.emptyList():r.body().getTecnicos());}public void onFailure(Call<UbicacionesTecnicosResponse>c,Throwable t){}});}}
